struct Record { int value; };

std::vector<Record> createRecords(unsigned int num, unsigned int minValue, unsigned int maxValue) {
    if (num <= 0 || minValue >= maxValue) {
        SPDLOG_ERROR("Invalid input parameters: number of records must be positive and range should be valid.");
        throw std::invalid_argument("Invalid input parameters");
    }

    boost::mt19937 engine(std::time(nullptr));
    boost::uniform_int_distribution<> dist(minValue, maxValue);

    std::vector<Record> records(num);
    for (auto& record : records) {
        record.value = dist(engine);
    }

    return records;
}

