        pthread_create(&input_threads[i], NULL, process_input, NULL);
    }

    // Wait for all input threads to finish
    for (int i = 0; i < sizeof(input_threads) / sizeof(pthread_t); ++i) {
        pthread_join(input_threads[i], NULL);
    }

    save_buffer_to_disk();  // Save the final buffer content to disk
    fclose(temp_file);

    return 0;
}

void* process_input(void* arg) {
    char line[256];
    while (true) {
        // Read a line from standard input
        if (!fgets(line, sizeof(line), stdin)) break;

