    const char* str = (const char*)line_ptr;

    if (validate_integer(str)) {
        // Lock the buffer mutex to ensure safe access
        pthread_mutex_lock(&buffer_mutex);

        // Insert the validated integer into the buffer, handling overflow with the temporary file
        if (buffer_index < MAX_BUFFER_SIZE) {
            buffer[buffer_index++] = atoi(str);
        } else {
