import hashlib
import hmac
import os
import sys
from io import BytesIO
from concurrent.futures import ThreadPoolExecutor, as_completed
from typing import Dict, Tuple, Callable, Union
import requests
import boto3
from botocore.exceptions import NoCredentialsError
import logging

class FileDownloader:
    def __init__(self, priority_function: Callable[[str], int], temp_storage_service: str, cloud_storage: str, log_level: str):
        self.priority_function = priority_function
        self.temp_storage_service = temp_storage_service
        self.cloud_storage = cloud_storage
        self.session = requests.Session()
        self.s3 = boto3.client(self.cloud_storage, region_name="us-west-2")  # Set your preferred AWS region here
        self.log = logging.getLogger(__name__)
        self.log.setLevel(getattr(logging, log_level))

    def download_file(self, url: str, local_path: str) -> None:
        try:
            remote_checksum = self.__calculate_remote_checksum(url)
            temp_path = f"{temp_storage_service}/{os.path.basename(url)}"

            if not os.path.exists(local_path):
                os.makedirs(local_path, exist_ok=True)

            if not self.__file_is_downloaded(temp_path):
                self.__download_from_temp(url, temp_path)

            if self.__check_integrity(remote_checksum, temp_path, local_path):
                os.rename(temp_path, local_path)
            else:
                self.__retry_partial_download(url, temp_path, local_path)
        except Exception as e:
            self.log.error(f"Error downloading file from {url}: {str(e)}")
            raise

    def __calculate_remote_checksum(self, url: str) -> bytes:
        response = self.session.get(url, stream=True)
        hasher = hashlib.sha256()
        for block in response.iter_content(1024):
            hasher.update(block)
        return hasher.digest()

    def __file_is_downloaded(self, file_path: str) -> bool:
        if not os.path.exists(file_path):
            return False
        file_size = os.path.getsize(file_path)
        chunk_size = 1024 * 1024
        with open(file_path, 'rb') as f:
            last_block = f.read(chunk_size)
        return bool(last_block) and file_size >= len(last_block)

    def __download_from_temp(self, url: str, temp_path: str) -> None:
        self.session.get(url, stream=True).raw.decode_content = True
        with open(temp_path, 'wb') as f:
            for block in self.session.get(url, stream=True).iter_content(1024):
                f.write(block)

    def __check_integrity(self, remote_checksum: bytes, temp_path: str, local_path: str) -> bool:
        local_checksum = self.__calculate_local_checksum(temp_path)
        return hmac.compare_digest(remote_checksum, local_checksum)

    def __calculate_local_checksum(self, file_path: str) -> bytes:
        hasher = hashlib.sha256()
        with open(file_path, 'rb') as f:
            for block in iter(lambda: f.read(1024 * 64), b""):
                hasher.update(block)
        return hasher.digest()

    def __retry_partial_download(self, url: str, temp_path: str, local_path: str) -> None:
        # Implement retry logic based on business rules and network conditions
        pass

    def download_files(self, urls_and_paths: Dict[str, str], concurrent_limit=5, retries=3) -> None:
        with ThreadPoolExecutor(max_workers=concurrent_limit) as executor:
            futures = [executor.submit(self.download_file, url, local_path) for url, local_path in sorted(urls_and_paths.items(), key=self.priority_function)]
            for _ in range(retries):
                for future in as_completed(futures):
                    try:
                        future.result()
                    except Exception as e:
                        self.log.error(f"Error downloading file: {str(e)}")

def test_file_download():
    downloader = FileDownloader(lambda x: len(x), "S3", "s3", "INFO")
    urls_and_paths = {"url1": "/local/path1", "url2": "/local/path2"}
    downloader.download_files(urls_and_paths)
