package com.pokemon.battleReportService;

import java.util.ConcurrentHashMap;
import java.util.Map;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import com.pokemonDetailsApiClient.PokemonDetailsApiClient;
import com.strategies.BattleStrategyGenerator;
import com.cache.ThreadSafeCache;
import com.translator.TranslationService;

public class BattleReportService {
    private static final Logger LOGGER = LoggerFactory.getLogger(BattleReportService.class);
    private static final int CACHE_SIZE = 1000;
    private static final long CACHE_EVICTION_TIME = TimeUnit.HOURS.toMillis(24);

    private ThreadSafeCache<String, PokemonDetails> cache;
    private BattleStrategyGenerator strategyGenerator;
    private PokemonDetailsApiClient apiClient;
    private TranslationService translationService;

    public BattleReportService(BattleStrategyGenerator strategyGenerator, PokemonDetailsApiClient apiClient, TranslationService translationService) {
        this.strategyGenerator = strategyGenerator;
        this.apiClient = apiClient;
        this.translationService = translationService;
        this.cache = new ThreadSafeCache<>(CACHE_SIZE);
    }

    public String generateBattleReport(String pokemonName, Language language) throws ExecutionException, InterruptedException {
        PokemonDetails pokemon = getOrFetchPokemonDetails(pokemonName);
        BattleStrategy strategy = strategyGenerator.generate(pokemon);
        return translationService.translate(strategy.getReport(), language);
    }

    private PokemonDetails getOrFetchPokemonDetails(String pokemonName) {
        Future<PokemonDetails> future = cache.get(pokemonName, () -> apiClient.getPokemonDetails(pokemonName));
        if (future != null && !future.isDone()) {
            return future.get();
        }
        PokemonDetails pokemonDetails = future != null ? future.get() : apiClient.getPokemonDetails(pokemonName);
        cache.put(pokemonName, pokemonDetails);
        return pokemonDetails;
    }
}
