['```csharp
using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using System.Timers;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;

public class UpdateService
{
    private readonly ILogger<UpdateService> _logger;
    private readonly HttpClient _cdnClient;
    private readonly string _loggingApiUrl;
    private readonly TimeSpan _retryInterval = TimeSpan.FromSeconds(2);
    private readonly ConcurrentDictionary<Guid, (Task task, DateTime lastAttemptedAt)> _updateTasks = new();

    public UpdateService(ILogger<UpdateService> logger, HttpClient cdnClient, string loggingApiUrl)
    {
        _logger = logger;
        _cdnClient = cdnClient;
        _loggingApiUrl = loggingApiUrl;
    }

    public async Task UpdateHtmlContentAsync(Guid pageSectionId, Guid elementId, string htmlContent)
    {
        if (string.IsNullOrEmpty(htmlContent))
        {
            throw new ArgumentException("HTML content must not be null or empty.");
        }

        var requestData = new UpdateRequestData
        {
            PageSectionId = pageSectionId,
            ElementId = elementId,
            HtmlContent = htmlContent
        };

        lock (_updateTasks)
        {
            if (_updateTasks.ContainsKey(requestData.GetHashCode()))
            {
                var existingTask = _updateTasks[requestData.GetHashCode()];

                if (!existingTask.task.IsCompleted && (DateTime.UtcNow - existingTask.lastAttemptedAt) < _retryInterval)
                {
                    await Task.DelayUntil(() => DateTime.UtcNow >= existingTask.lastAttemptedAt.Add(_retryInterval));
                    return;
                }

                _updateTasks.TryRemove(requestData.GetHashCode(), out _);
            }
        }

