{
    // Database connection and query to get current status, last modified IP, and last modified date for given clinic ID
    // ...

    try {
        // API call to fetch the new status
        $client = new Client([...]);
        $response = $client->get($api['base_uri'] . 'clinic/' . $clinicId);

        if ($response->getStatusCode() == 200) {
            // Update the clinic status, last modified IP address, and last modified date in the database using the new data from API
            // ...
        } else {
            error_log("Failed to fetch clinic status from API: " . $response->getStatusCode());
        }
    } catch (\Exception $e) {
        error_log($e->getMessage());
    }
}

$app = AppFactory::create();

// Concurrency control using semaphore mechanism with 10 concurrent requests
$semaphore = new Semaphore(10);

$app->options('/', function (Request $request, Response $response, callable $next) {
    return $next($request, $response);
});

$app->get('/update/{clinicId}', function (Request $request, Response $response, array $args) use ($semaphore) {
    $clinicId = intval($args['clinicId']);

    // Acquire semaphore to prevent race conditions during high traffic periods
    if (!$semaphore->acquire()) {
        return $response->withStatus(503)->getBody()->write("Service busy, try again later.");
    }

    updateClinicStatus($clinicId, $semaphore);

    // Release semaphore after the operation is completed
    $semaphore->release();

    return $response->withStatus(200)->getBody()->write("Successfully updated clinic status.");
});

$app->run();
```

