['```php
<?php

class UserService {
    private $db;
    private $idp;
    private $queue;
    private $commandRunner;

    public function __construct(PDO $db, ExternalIDP $idp, CommandRunner $commandRunner, Queue $queue) {
        $this->db = $db;
        $this->idp = $idp;
        $this->commandRunner = $commandRunner;
        $this->queue = $queue;
    }

    public function updatePassword($userId, $newPassword, $command) {
        if (!$this->validatePassword($newPassword)) {
            return ["success" => false, "message" => "Invalid password"];
        }

        try {
            $this->db->beginTransaction();
            $this->db->exec("UPDATE users SET password = ? WHERE id = ?", [hash($newPassword), $userId]);
            $this->db->commit();
        } catch (Exception $e) {
            $this->db->rollback();
            if ($this->retryDatabaseConnection()) {
                return $this->updatePassword($userId, $newPassword, $command);
            } else {
                return ["success" => false, "message" => "Database error"];
            }
        }

        $this->queue->enqueue(["command" => $command, "user_id" => $userId]);

        try {
            $this->commandRunner->run($command);
        } catch (Exception $e) {
            return ["success" => false, "message" => "Command execution error"];
        }

        return ["success" => true];
    }

    private function validatePassword($password) {
        // Validate password against complex criteria using the external IDP
        if (!$this->idp->validatePasswordStrength($password)) {
            $errors = $this->idp->getValidationErrors();
            return array_merge([false], $errors);
        }

        return [true];
    }

    private function retryDatabaseConnection() {
        static $retries = 0;

        if ($retries >= 3) {
            return false;
        }

        try {
            $this->db->connect();
            $retries++;
            return true;
        } catch (Exception $e) {
            return $this->retryDatabaseConnection();
        }
    }
}
```

This code is for the `UserService` class and assumes you have defined classes for the external IDP, database connection, command runner, and queue system. The code covers points 1-6 of your task requirements.']

