using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

namespace SecureRandomValueGenerator
{
    public class SecureRangeConfig
    {
        public long Min { get; set; }
        public long Max { get; set; }
        public byte[] Seed { get; set; }

        public SecureRangeConfig(long min, long max, byte[] seed)
        {
            if (min >= max) throw new ArgumentException("The minimum value must be less than the maximum value.");
            if (seed == null || seed.Length < 16) throw new ArgumentException("The seed must be at least 16 bytes long for cryptographic purposes.");
            Min = min;
            Max = max;
            Seed = seed;
        }
    }

    public class SecureRandomValueGenerator
    {
        private RNGCryptoServiceProvider _rngCrypto = new RNGCryptoServiceProvider();
        private long _min, _max;
        private byte[] _seed;
        private readonly object _locker = new object();

        public SecureRandomValueGenerator(SecureRangeConfig config)
        {
            if (config == null) throw new ArgumentNullException(nameof(config));
            _min = config.Min;
            _max = config.Max;
            _seed = config.Seed;
        }

        public SecureRandomValueGenerator SetSeed(byte[] seed)
        {
            if (seed == null || seed.Length < 16) throw new ArgumentException("The seed must be at least 16 bytes long for cryptographic purposes.");
            lock (_locker) _rngCrypto.SetBytes(seed);
            return this;
        }

        public double NextDouble() => (double)_rngCrypto.GetBytes(new byte[4])[0] / byte.MaxValue * (_max - _min) + _min;

        public long Next() => (long)(NextDouble() * (_max - _min + 1)) + _min;

        public SecureRangeConfig CurrentConfig => new SecureRangeConfig(_min, _max, GetSeedBytes());

        private byte[] GetSeedBytes() => _rngCrypto.GetBytes(16);

        public override string ToString() => $"SecureRandomValueGenerator: [Min={_min}, Max={_max}, Seed={string.Join(" ", GetSeedBytes().Take(4).Select(b => b.ToString("X2")))}..."]";
    }
}
```

