using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;

namespace SecureDataRehydration
{
    public class EncryptedDataset
    {
        public string Data { get; set; }
        public string Checksum { get; set; }
    }

    public class Config
    {
        public string EncryptionServiceUrl { get; set; }
        public string StorageProviderUrl { get; set; }
        public string AccessToken { get; set; }
        public string KeyRotationInterval { get; set; }
    }

    public class SecureDataRehydration
    {
        private readonly Config _config;
        private readonly HttpClient _httpClient;
        private readonly Aes _aes;

        public SecureDataRehydration(Config config)
        {
            _config = config;
            _httpClient = new HttpClient();
            using (Aes aes = Aes.Create())
            {
                _aes = aes;
            }
        }

        public async Task<EncryptedDataset> SecureDataRehydrationAsync(string datasetId, string localFile)
        {
            try
            {
                // Load encrypted data from the cloud repository
                var response = await _httpClient.GetAsync($"{_config.StorageProviderUrl}/{datasetId}");
                if (!response.IsSuccessStatusCode)
                    throw new Exception($"Failed to download encrypted dataset: {response.StatusCode}");

                // Decrypt the data using AES-CBC with a random IV
                var decryptionTask = DecryptDataAsync(response.Content.ReadAsByteArrayAsync().Result);

                // Load the checksum from the response headers or metadata
                var checksum = response.Headers.GetValues("X-Checksum").FirstOrDefault();
                if (string.IsNullOrEmpty(checksum))
                    throw new Exception("Missing checksum in response headers");

                // Deserialize the data and compare the computed checksum with the received one
                using (var stream = File.OpenRead(localFile))
                {
                    var deserializedData = await Task.Run(() => JsonConvert.DeserializeObject<EncryptedDataset>(await new StreamReader(stream).ReadToEnd()));

                    if (!deserializedData.Checksum.SequenceEqual(HashUtil.ComputeSha256(decryptionTask.Result)))
                        throw new Exception("Data integrity checksum mismatch");

                    return deserializedData;
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"An error occurred during data rehydration: {ex}");
                throw;
            }
        }

        private async Task<byte[]> DecryptDataAsync(ByteArrayContent encryptedData)
        {
            // Decrypt the encrypted data using the AES key and IV, which are rotated regularly according to the config
            var decryptionStream = new MemoryStream();
            using (var cryptoStream = _aes.CreateDecryptor().CreateCryptoStream(decryptedData, decrypting => decryptedData.WriteTo(decrypting)))
            {
                cryptoStream.CopyToAsync(decryptionStream);
            }
            return await Task.FromResult(decryptionStream.ToArray());
        }

        private static class HashUtil
        {
            public static byte[] ComputeSha256(byte[] data) => SHA256.Create().ComputeHash(data);
        }
    }
}
```
