char* validateAndAppendSuffix(const char* input, int sizeLimit, bool isSecure, const char* jsonString, onErrorCallback onError) {
    // Validate and parse JSON string
    json_object *json = json_tokener_parse(jsonString);

    if (!json || !json_object_get_exact(json, "access_token")) {
        onError("JSON is malformed or missing access_token");
        json_object_put(json); // Free the parsed JSON object
        return NULL;
    }

    // Access the token and its associated properties
    const char *accessToken = json_object_get_string(json_object_get_exact(json, "access_token"));
    int expiresIn = json_object_get_int(json_object_get_exact(json, "expires_in"));
    const char *tokenType = json_object_get_string(json_object_get_exact(json, "token_type"));

    // Validate the token type and lifetime
    if (strcmp(tokenType, "Bearer") != 0 || expiresIn <= 0) {
        onError("Invalid OAuth2 access token");
        json_object_put(json); // Free the parsed JSON object
        return NULL;
    }

    pthread_mutex_lock(&mutex);

    // Validate the token asynchronously using a separate thread and external API
    void* validateTokenResult = validateTokenAsync(accessToken, onError, sizeLimit, isSecure);

    pthread_mutex_unlock(&mutex);

    if (validateTokenResult == NULL) {
        return NULL; // Token validation failed or was not performed due to transient errors
    }

    // Assemble and return the output string with or without suffix
    strncpy(outputBuffer, input, sizeLimit);
    if ((strlen(input) <= sizeLimit) && isSecure == *(bool*)validateTokenResult) {
        strcat(outputBuffer, "Secure");
    } else {
        strcat(outputBuffer, "Non-Secure");
    }

    return strdup(outputBuffer);
}

