['```csharp
using System;
using System.Collections.Generic;
using System.Data.Common;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using StackExchange.Redis;
using Dapper;

public class DatabaseService
{
    private readonly ILogger<DatabaseService> _logger;
    private readonly IDbConnectionFactory _connectionFactory;
    private readonly ConnectionMultiplexer _redis;

    public DatabaseService(ILogger<DatabaseService> logger, IOptionsMonitor<DatabaseOptions> options, IServiceProvider serviceProvider)
    {
        _logger = logger;
        var dbConnectionString = options.CurrentValue.ConnectionString;
        _connectionFactory = serviceProvider.GetRequiredService<IDbConnectionFactory>();
        _redis = ConnectionMultiplexer.Connect(options.CurrentValue.RedisConnectionString);
    }

    public async Task<SqlDataReader> ExecuteParameterizedQueryAsync(string command, List<object> parameters)
    {
        var connection = await GetConnectionAsync().ConfigureAwait(false);
        using (connection)
        {
            return await ExecuteQueryInternalAsync(connection, command, parameters).ConfigureAwait(false);
        }
    }

    private async Task<DbConnection> GetConnectionAsync()
    {
        var cacheKey = "DatabaseConnection";
        if (_redis.IsConnected)
        {
            DbConnection connection;
            if ((connection = _redis.GetDatabase().GetHashValue(cacheKey).ToObject<DbConnection>()) != null)
            {
                return connection;
            }
        }

        var connection = _connectionFactory.CreateConnection();
        connection.Open();
        await SetConnectionInCacheAsync(connection).ConfigureAwait(false);
        return connection;
    }

    private async Task SetConnectionInCacheAsync(DbConnection connection)
    {
        if (_redis.IsConnected)
        {
            _redis.GetDatabase().HashSet(cacheKey, connection);
        }
    }

    private async Task<SqlDataReader> ExecuteQueryInternalAsync(DbConnection connection, string command, List<object> parameters)
    {
        try
        {
            return await connection.QueryAsync(command, parameters).ConfigureAwait(false);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to execute query: {Command}", command);
            if (IsTransientFailure(ex))
            {
                await RetryQueryAsync(connection, command, parameters).ConfigureAwait(false);
            }
            throw;
        }
    }

    private bool IsTransientFailure(Exception ex)
    {
        // Implement your logic to determine if the failure is transient based on the exception type or message.
    }

    private async Task RetryQueryAsync(DbConnection connection, string command, List<object> parameters)
    {
        var backoff = TimeSpan.FromMilliseconds(100);
        int retryAttempts = 3;

        while (retryAttempts-- > 0)
        {
            try
            {
                return await ExecuteQueryInternalAsync(connection, command, parameters).ConfigureAwait(false);
            }
            catch (Exception ex) when (IsTransientFailure(ex))
            {
                _logger.LogInformation("Retrying query execution due to transient failure: {Command}", command);
                await Task.Delay(backoff).ConfigureAwait(false);
                backoff = backoff * 2;
            }
        }

        throw new Exception($"Failed to execute query after {retryAttempts} retries: {command}");
    }
}
```

This code assumes you are using dependency injection (Microsoft.Extensions), Dapper for SQL queries, and StackExchange.Redis for caching connections. The `DatabaseOptions` class should contain the connection strings for the database and redis. You will need to implement the `IsTransientFailure` method based on your specific error handling requirements.

Keep in mind that this code does not include any testing, monitoring, or fault tolerance mechanisms for scaling horizontally across multiple servers, as those would require a more complex setup outside the scope of this example.']

