app.get('/employees/:supervisorId', async (req, res) => {
  const supervisorId = req.params.supervisorId;
  let cacheKey = `employee_${supervisorId}`;

  if (cache.get(cacheKey)) {
    return res.json(cache.get(cacheKey)); // Return from cache if available
  }

  try {
    const result = await db.request()
      .query('SELECT name, city, address FROM Employees WHERE supervisor_id = @supervisorId', { input: { supervisorId } });

    // Store the result in cache and send response
    cache.set(cacheKey, result.recordset);
    return res.json(result.recordset);
