3. Create a separate source file `MD5Hash.cpp`:

```cpp
#include "ImageProcessing.h"
#include <openssl/md5.h>

std::vector<uint8_t> computeMD5Hash(const std::string& str) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    uint8_t hashedStr[str.length() + MD5_DIGEST_LENGTH];

    // Hash the input string using OpenSSL's MD5 function.
    const char* strPtr = str.c_str();
    size_t strLen = strlen(strPtr);
    memcpy(hashedStr, strPtr, strLen);
    MD5((const unsigned char*) hashedStr, strLen, digest);

    std::copy(std::begin(digest), std::end(digest), std::begin(hashedStr) + strLen);
    return {hashedStr, hashedStr + MD5_DIGEST_LENGTH};
}
```

