    private readonly ConcurrentDictionary<string, KeyVault> _keyVaultCache;
    private readonly TimeSpan _logRetentionPeriod;
    private readonly int _maxConcurrentOperations;

    public SecureDataRehydration(string keyStorageUrl, ILogger logger, TimeSpan logRetentionPeriod = TimeSpan.FromDays(30), int maxConcurrentOperations = 10)
    {
        _keyStorageUrl = keyStorageUrl;
        _logger = logger;
        _logRetentionPeriod = logRetentionPeriod;
        _maxConcurrentOperations = maxConcurrentOperations;
        _keyVaultCache = new ConcurrentDictionary<string, KeyVault>();
