    public async Task<T> DecryptAndDeserializeAsync<T>(string datasetId)
    {
        if (!_keyVaultCache.TryAdd(datasetId, await LoadKeyVaultAsync(datasetId))) return default;

        var encryptedData = await FetchEncryptedDataAsync(datasetId);

        using (var aes = Aes.Create())
        {
            await UsingKey(aes.Key, datasetId, async () =>
            {
                using (var gcm = new AESEngine(aes))
                {
                    var plainTextBytes = await gcm.Decrypt(encryptedData, out _);
                    return JsonConvert.DeserializeObject<T>(Encoding.UTF8.GetString(plainTextBytes));
                }
            });
        }
    }

