    private async Task UsingKey(byte[] key, string datasetId, Func<Task<T>> action)
    {
        var lockToken = GetLockToken(datasetId);
        await AcquireDistributedLockAsync(lockToken);

        try
        {
            using (var rsa = RSA.Create())
