    }
}

async fn run(args: Vec<String>) {
    let timeout = Duration::from_secs(match args.get(0).and_then(|s| s.parse::<u64>().ok()) {
        Some(v) if v > 60 => Duration::from_secs(v),
        _ => Duration::from_secs(10),
    });

    let concurrency = match args.get(1).and_then(|s| s.parse::<u32>().ok()) {
        Some(v) if v > 100 => 100,
        _ => 10,
    };

    let limit = ConcurrencyLimitLayer::new(concurrency);
    let retry = RetryLayer::new().max_retries(5).on_response(|_, res| {
        if res.is_err() && res.contexts().contains(&tower::CircuitBreakerContext) {
            Error::new(tower::ErrorKind::CircuitBreakerOpen)
        } else {
            res
        }
    });
    let rate_limited = LazyLayer::new(move || limit.then(retry));

    let client = Client::builder()
        .timeout(Timeout::new(timeout))
        .build()
        .expect("Failed to build HTTP client");

    let api_metrics = Arc::new(RwLock::new(ApiMetrics::default()));
    let error_count = Arc::new(RwLock::new(ErrorCount::default()));

    ThirdPartyApiClient {
        client,
        api_metrics,
        error_count,
    }
    .into_service()
    .serve_async_stream(move |req| {
        let (tx, rx) = oneshot::channel();
        let api_metrics = api_metrics.clone();
        let error_count = error_count.clone();

        async move {
            match req.await {
                Ok(res) => {
                    let _ = tx.send(res);
                    info!("API request successful");
                }
                Err(e) => {
                    error!("API request failed: {}", e);

                    if let Some(_) = api_metrics.write().await.inc_error() {
                        error_count.write().await.inc();
                    }

                    _ = tx.send(Err(e));
                }
            }
        }
        .layer(rate_limited)
    })
}

#[tokio::main]
async fn main() {
    env_logger::init();

    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        eprintln!("Usage: {} <timeout_seconds> [concurrency]", args[0]);
        std::process::exit(1);
    }

    run(args).await;
}

