['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <pthread.h>
#include <json-c/json.h>

typedef struct {
    pthread_t token_validation_thread;
    int size_limit;
    bool is_secure;
    char *dir_name, *env_var_name, *json_string;
    void (*on_error)(const char*);
} create_dir_params;

static pthread_mutex_t token_cache_mutex = PTHREAD_MUTEX_INITIALIZER;
static char token_cache[1024] = {0}; // Pre-allocated buffer for cached tokens
static int cache_size = 0;
static const int MAX_RETRIES = 3;
static const int RETRY_DELAY_MS = 500;

int create_directory(const char* dir_name) {
    mkdir(dir_name, S_IRWXU | S_IRGRP | S_IXGRP | S_IROTH | S_IXOTH);
    return !access(dir_name, F_OK);
}

void set_env_var(const char* env_var_name, const char* dir_path) {
    char *env = getenv(env_var_name);
    if (!env) {
        putenv(strdup(env_var_name "=" dir_path));
    }
}

bool is_valid_token(const char* json_string) {
    struct json_object *json = json_tokener_parse(json_string, 0);
    if (IS_ERR(json)) return false;

    struct json_object *token_type_obj = json_object_object_get(json, "token_type");
    const char* token_type = json_object_get_string(token_type_obj);
    if (strcmp(token_type, "Bearer") != 0) return false;

    struct json_object *expires_in_obj = json_object_object_get(json, "expires_in");
    int expires_in = json_object_get_int(expires_in_obj);
    return expires_in > 0;
}

void on_error(const char* error_msg) {
    if (params->on_error) params->on_error(error_msg);
}

char* createDirAndSetEnv(create_dir_params *params) {
    const char* dir_path = mkdtemp(params->dir_name);
    if (!dir_path) return NULL;

    set_env_var(params->env_var_name, dir_path);

    if (create_directory(params->dir_name)) {
        pthread_t token_validation_thread = params->token_validation_thread;
        params->token_validation_thread = 0;
        if (!is_valid_token(params->json_string)) {
            params->is_secure = false;
        } else {
            pthread_mutex_lock(&token_cache_mutex);
            if (cache_size + strlen(dir_path) < sizeof(token_cache)) {
                strcpy(token_cache + cache_size, dir_path);
                cache_size += strlen(dir_path) + 1;
            } else {
                free(token_cache);
                token_cache = realloc(token_cache, cache_size * 2);
                strcpy(token_cache + cache_size - strlen(dir_path), dir_path);
                cache_size += strlen(dir_path) + 1;
            }
            pthread_mutex_unlock(&token_cache_mutex);

            params->token_validation_thread = token_validation_thread;
        }
    } else {
        on_error("Failed to create directory");
    }

    free(params->json_string);
    free(params);

    if (params->is_secure) return strdup("Secure");
    return strdup("Non-Secure");
}

void* token_validation_thread(void *param) {
    create_dir_params *params = param;
    while (true) {
        int retries = MAX_RETRIES;
        while (retries > 0 && !is_valid_token(params->json_string)) {
            usleep(RETRY_DELAY_MS * 1000);
            retries--;
        }

        if (retries == 0) {
            on_error("Token validation failed after maximum retries");
            free(params->json_string);
            free(param);
            return NULL;
        }

        params->is_secure = true;
        pthread_mutex_lock(&token_cache_mutex);
        char *cached_dir_path = strchr(token_cache, params->env_var_name[0]);
        if (cached_dir_path) {
            strncpy(params->json_string, cached_dir_path, params->size_limit);
            params->json_string[params->size_limit] = '\0';
        } else {
            free(param);
            return NULL;
        }
        pthread_mutex_unlock(&token_cache_mutex);
    }
}
```

