      ```cpp
      // JavaScript execution example
      #include <process>
      #include <iostream>

      void executeJS(const std::string& command) {
        std::array<char, 128> buffer;
        std::streambuf *old = std::cerr.rdbuf(buffer.data());
        std::string output;
        std::string error;
        std::process::child process(std::process::command("node").arg("-e").arg(command));

        process.async_wait([&](const std::error_code& ec, int pid) {
          if (ec) {
            // Handle errors
          } else {
            output += process.get_exit_code() == 0 ? process.get_out_stream().rdbuf()->str() : process.get_err_stream().rdbuf()->str();
          }
        });

        process.wait_for(std::chrono::seconds(5)); // Timeout after 5 seconds
        if (process.wait_and_get_exit_code() != 0) {
          error += buffer.data();
        } else {
          output += buffer.data();
        }
        std::cerr.rdbuf(old);
        // Output the result to the browser
        std::cout << output;
      }
      ```

