State* create_state_linked_list(int *states, int num_states, const FSA *fsa, int last_state) {
    if (!states || !num_states || !fsa || last_state < 0) return NULL;

    State *head = NULL, *current = NULL;
    for (int i = 0; i < num_states; ++i) {
        State *new_state = validate_state(states[i]);
        if (!new_state) continue;
        new_state->id = states[i];

        sem_wait(&mutex);
        if (head == NULL) {
            head = current = new_state;
        } else {
            current->next = new_state;
            current = current->next;
        }
        sem_post(&mutex);
    }

    // Implement concurrent access and updates, transactions, etc.

    return head;
}
