line_t* dequeue(void** queue) {
    line_t* res = *queue;
    if (res) {
        *queue = res->next;
        free(res);
    }
    return res;
}

void enqueue(line_t** queue, const char* data, size_t size) {
    line_t* new_node = mmap(NULL, sizeof(line_t), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (new_node == MAP_FAILED) {
        // Handle error
    }
    new_node->data = mmap(NULL, size + 1, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (new_node->data == MAP_FAILED) {
        // Handle error
    }
    memcpy(new_node->data, data, size);
    new_node->size = size;
    new_node->next = *queue;
