import time

class ExponentialBackoff:
    def __init__(self, max_attempts=5, initial_delay=1):
        self.max_attempts = max_attempts
        self.initial_delay = initial_delay
        self.current_attempt = 0
        self.reset()

    def reset(self):
        self.current_attempt = 0

    def increment(self):
        self.current_attempt += 1

    def should_retry(self):
        return self.current_attempt < self.max_attempts

# utils/circuit_breaker.py
import time
import math

class CircuitBreaker:
    def __init__(self, request_timeout=10, half_open_time=30):
        self.request_timeout = request_timeout
        self.half_open_time = half_open_time
        self.is_open = False
        self.last_failure_time = 0

    def is_open(self):
        return self.is_open

    def call(self, fn):
        def wrapper(*args, **kwargs):
            if not self.is_open:
                try:
                    result = fn(*args, **kwargs)
                    self.reset()
                    return result
                except Exception as e:
                    self.mark_failure()
                    raise e
            else:
                self.mark_failure()
                raise RuntimeError("Circuit breaker is open.")

        return wrapper

    def mark_failure(self):
        current_time = time.time()
        if (current_time - self.last_failure_time) < self.half_open_time:
            self.is_open = True
        else:
            self.is_open = False
        self.last_failure_time = current_time

# monitoring/monitoring.py
import logging
import time

class Monitoring:
    def __init__(self):
        self.logger = logging.getLogger(__name__)

    def monitor(self, callback):
        start_time = time.time()
        result = callback()
        end_time = time.time()
        self.log_metrics(start_time, end_time)
        return result

    def log_metrics(self, start_time, end_time):
        elapsed_time = end_time - start_time
        self.logger.info(f"Elapsed time: {elapsed_time} seconds")
```

