```cpp
class Retry {
public:
    explicit Retry(int maxRetries, int backoff) : retries(maxRetries), backoff(backoff) {}

    void operator()(const std::function<void()>& func) {
        for (int i = 0; i < retries; ++i) {
            try {
                func();
                return;
            } catch (...) {
                if (i + 1 >= retries || std::chrono::system_clock::now().time_since_epoch() > lastRetryTime + backoff * std::chrono::milliseconds(i)) {
                    throw;
                }
            }
        }
    }
private:
    int retries, backoff;
    std::chrono::system_clock::time_point lastRetryTime = std::chrono::system_clock::now();
};
```

