size_t load_resource_bundle(char *path, struct resource **bundle) {
    FILE *file = fopen(path, "r");
    if (!file) {
        perror("Error opening file");
        return 0;
    }

    fseek(file, 0, SEEK_END);
    size_t bundle_size = ftell(file);
    rewind(file);

    *bundle = malloc(sizeof(struct resource));
    (*bundle)->data = malloc(bundle_size + 1);
    (*bundle)->size = fread((*bundle)->data, sizeof(char), bundle_size, file);
    (*bundle)->data[(*bundle)->size] = '\0';
    fclose(file);

    return (*bundle)->size;
}
```

2. OAuth Request to PEM Certificate Conversion Function (oauth_request_to_pem):

```c
#include <openssl/pem.h>
#include <openssl/err.h>

int oauth_request_to_pem(char *path, EVP_PKEY **key) {
    FILE *file = fopen(path, "r");
    if (!file) {
        perror("Error opening file");
        return 0;
    }

    X509 *certificate = PEM_read_X509(file, NULL, NULL, NULL);
    EVP_PKEY *key_ptr = X509_get_pubkey(certificate);
    *key = key_ptr;

    fclose(file);
    return 1;
}
