using System;
using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Mvc;
using Newtonsoft.Json;

namespace MyApi.Controllers
{
    [Route("api/[controller]")]
    public class DecryptController : Controller
    {
        private readonly TripleDESCryptoServiceProvider _crypto;

        public DecryptController()
        {
            var key = new byte[] { 0x12, 0x34, 0x56, 0x78, 0x90, 0xAB, 0xCD, 0xEF };
            var iv = new byte[] { 0x36, 0x57, 0x78, 0x90, 0xAB, 0xCD, 0xEF, 0xFE };
            _crypto = new TripleDESCryptoServiceProvider { Key = key, IV = iv };
        }

        [HttpGet("decrypt/{base64EncodedInput}")]
        public ActionResult<string> Decrypt(string base64EncodedInput)
        {
            try
            {
                var inputBytes = Convert.FromBase64String(base64EncodedInput);
                var decryptedBytes = Decrypt(inputBytes);
                return Ok(Encoding.UTF8.GetString(decryptedBytes));
            }
            catch (Exception ex)
            {
                return BadRequest($"Error decrypting data: {ex.Message}");
            }
        }

        private byte[] Decrypt(byte[] inputBytes)
        {
            using (var ms = new MemoryStream(inputBytes))
            {
                var encryptedBytes = new byte[ms.Length];
                ms.Read(encryptedBytes, 0, encryptedBytes.Length);
                return Decrypt(encryptedBytes);
            }
        }

        private byte[] Decrypt(byte[] inputBytes)
        {
            var decryptor = _crypto.CreateDecryptor();
            using (var ms = new MemoryStream(inputBytes))
            {
                using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                    return cs.ToArray();
            }
        }
    }
}
```']

