/* Function: checkAndAppendSlash
 * Description: Checks if the given string does not exceed the specified size limit
 *              and appends a slash at the end if it's within the limit. Returns NULL if the string exceeds the limit.
 */
char* checkAndAppendSlash(const char* input, size_t limit) {
    size_t length = strlen(input);

    // Check if the input string does not exceed the specified size limit
    if (length > limit) {
        return NULL;
    }

    // Allocate memory for a new string of the same length as the input string, plus one extra byte for the appended slash
    char* output = malloc(length + 1);

    // Copy the input string to the output buffer and append a slash at the end
    strcpy(output, input);
    output[length] = '/';

    return output;
}

/* Unit tests for checkAndAppendSlash function */
