#include <stdio.h>

void test_checkAndAppendSlash() {
    const char* testCases[][2] = {
        {"abc", 4},     // within the limit
        {"abcd", 3},    // below the limit but with slash appended
        {"123456789", 10}   // above the limit
    };

    for (int i = 0; i < sizeof(testCases) / sizeof(char*); ++i) {
        char* result = checkAndAppendSlash(testCases[i][0], testCases[i][1]);
        if (result != NULL && strlen(result) == testCases[i][1] + 1) {
