    void insertAfter(const std::forward_list<std::string>& list, const std::string& target, const std::string& value) {
        auto it = list.begin();
        if (it == list.end()) {
            list.push_back(value);
            return;
        }

        for (; it != list.end(); ++it) {
            if (*it == target) {
