    retries = AUTH_RETRIES
    backoff_delay = 1

    while True:
        try:
            return function()
        except (NoCredentialsError, ClientError) as e:
            if retries == 0:
                raise e
            else:
                retries -= 1
                time.sleep(backoff_delay ** retries)
                backoff_delay *= 2

