```cpp
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>

int runCommand(const char* command) {
    pid_t child = fork();

    if (child == -1) {
        return 0; // Failed to fork
    } else if (child > 0) { // Parent process
        int status;
        waitpid(child, &status, 0);
        return WIFEXITED(status) ? WEXITSTATUS(status) == 0 : 0;
    } else { // Child process
        execlp(command, command, NULL);
        _exit(1); // Failed to execute the command
    }
}
```

