#include <stdio.h>
#include <string.h>
#include <errno.h>

char *addSlashIfNeeded(const char *input, size_t limit) {
    if (strlen(input) <= limit) {
        char *result = malloc((limit + 1) * sizeof(char));
        strcpy(result, input);
        result[limit] = '/';
        return result;
    } else {
        errno = ERANGE; /* Set errno to ERANGE for EOVERFLOW */
        perror("Input string exceeds the specified limit");
        return NULL;
    }
}

