#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>
#include <sys/mman.h>
#include <semaphore.h>

typedef struct {
    char name[256];
    size_t size;
    enum { TEXT, IMAGE, AUDIO } type;
} ResourceItem;

struct BundleLoader {
    void *file; // Mapped memory of the resource file
    size_t position; // Current position in the mapped memory
    sem_t sem_items_locked; // Semaphore to lock item access
    int verbosity;
};

int loadResourceBundle(const char *filename, struct BundleLoader **bundle) {
    void *file = mmap(NULL, strlen(filename) + sizeof(ResourceItem), PROT_READ, MAP_PRIVATE, fileno(fopen(filename, "rb")), 0);

    if (file == MAP_FAILED) {
        perror("mmap");
        return -1;
    }

    struct BundleLoader *bundle_ptr = malloc(sizeof(struct BundleLoader));
    memset(bundle_ptr, 0, sizeof(struct BundleLoader));
    bundle_ptr->file = file;
    bundle_ptr->sem_items_locked = sem_init(0, true, 1);
    *bundle = bundle_ptr;

    sem_wait(&bundle_ptr->sem_items_locked);

    int num_items = 0;
    while (num_items < INT_MAX && position < strlen(file)) {
        size_t header_size = parseHeader((char *)file + bundle_ptr->position, &bundle_ptr->position);
        if (header_size <= 0) {
            break;
        }

        ResourceItem *item = malloc(sizeof(ResourceItem));
        if (!parseItem((char *)file + bundle_ptr->position - header_size, item)) {
            free(item);
            sem_post(&bundle_ptr->sem_items_locked);
            return -1;
        }

        num_items++;
        bundle_ptr->position += header_size + item->size;
    }

    sem_post(&bundle_ptr->sem_items_locked);

    // Allocate dynamically-sized arrays for items and pointers to them
    ResourceItem **item_ptrs = malloc(num_items * sizeof(ResourceItem*));
    int i;
    sem_wait(&bundle_ptr->sem_items_locked);
    for (i = 0; i < num_items; ++i) {
        item_ptrs[i] = &((struct BundleLoader*) bundle)->items[i];
    }
    sem_post(&bundle_ptr->sem_items_locked);

    return num_items;
}

// Implement the rest of the functions (parseHeader, parseItem, etc.) and the async loading logic here
```

