void EncryptionService::processRequest(const std::string& password, const std::string& salt, const std::string& data) {
    // Validate input
    if (password.length() < 16 || password.length() > 64 || salt.length() != 16) {
        throw std::invalid_argument("Invalid format or length for password or salt.");
    }

    // Derive key from password and salt
    std::vector<uint8_t> key(AES_GCM::KEYBYTES);
    deriveKey();
    encryptData(key.data(), key.size(), data, key);

    // Store derived key securely within the service lifecycle
