    // Encrypt and save data to database
    std::vector<uint8_t> encrypted_data;
    encryptData(key.data(), key.size(), data, encrypted_data);
    db_->saveEncryptedData(encrypted_data);
}

void EncryptionService::deriveKey() {
    std::unique_lock<std::mutex> lock(pbkdf2_iterations_mutex_);
    unsigned int iterations = pbkdf2_iterations_;
    uint8_t key[AES_GCM::KEYBYTES];
    const char* password_bytes = password_.c_str();
    const char* salt_bytes = salt_.c_str();

    unsigned char kdk[EVP_MAX_KEY_LENGTH];
    EVP_PBE_key_and_iv(EVP_aes_256_gcm(), NULL, kdk, nullptr, password_bytes,
                      salt_bytes, iterations, 0);

    // Copy derived key to the AES-GCM key buffer
    std::copy(kdk, kdk + AES_GCM::KEYBYTES, key.begin());
}

