const regex = {
  book: /(\b(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)\b)/gi,
  number: /\d+/g
};
function findBooks(text) {
  const matches = text.match(regex.book);
  const books = {};
  if (matches) {
    matches.forEach((bookName) => {
      if (!books[bookName]) books[bookName] = 1;
      else books[bookName]++;
    });
    for (const [book, count] of Object.entries(books)) {
      const numberMatches = text.match(new RegExp(`\\b${book}\\s+(\\d+)\\b`, 'gi'));
      if (numberMatches) {
        numberMatches.forEach((match) => {
          const [, bookName, number] = match.match(/(\\w+)\\s+(\\d+)/);
          if (!isNaN(Number(number)) && books[bookName]) books[bookName][Number(number)]++;
        });
      }
    }
  }
  return books;
}
