typedef struct {
    LTEPHY_MEASUREMENT_RECORD *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
} dyn_list_t;

dyn_list_t *dyn_list_create(size_t initial_capacity) {
    dyn_list_t *list = mmap(NULL, sizeof(dyn_list_t), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    list->data = mmap(NULL, initial_capacity * sizeof(LTEPHY_MEASUREMENT_RECORD), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->not_empty, NULL);
    return list;
}

void dyn_list_destroy(dyn_list_t *list) {
    munmap(list->data, list->capacity * sizeof(LTEPHY_MEASUREMENT_RECORD));
    munmap((void *)list, sizeof(dyn_list_t));
}

bool dyn_list_insert(dyn_list_t *list, const LTEPHY_MEASUREMENT_RECORD *record) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        void *new_data = mmap(NULL, (list->capacity * 2) * sizeof(LTEPHY_MEASUREMENT_RECORD), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        memmove(new_data, list->data, list->size * sizeof(LTEPHY_MEASUREMENT_RECORD));
        free(list->data);
        list->capacity *= 2;
        list->data = new_data;
    }
    memcpy(&list->data[list->size], record, sizeof(LTEPHY_MEASUREMENT_RECORD));
    list->size++;
    pthread_cond_signal(&list->not_empty);
    pthread_mutex_unlock(&list->lock);
    return true;
}

bool dyn_list_remove(dyn_list_t *list, time_t timestamp) {
    pthread_mutex_lock(&list->lock);
    size_t i = 0;
    for (; i < list->size; ++i) {
        if (list->data[i].timestamp == timestamp) {
            memmove(&list->data[i], &list->data[i+1], (list->size - i - 1) * sizeof(LTEPHY_MEASUREMENT_RECORD));
            list->size--;
            break;
        }
    }
    pthread_cond_signal(&list->not_empty);
    pthread_mutex_unlock(&list->lock);
    return i < list->size;
}

const LTEPHY_MEASUREMENT_RECORD *dyn_list_get(const dyn_list_t *list, time_t timestamp) {
    pthread_mutex_lock(&list->lock);
    size_t i = 0;
    for (; i < list->size; ++i) {
        if (list->data[i].timestamp == timestamp) {
            const LTEPHY_MEASUREMENT_RECORD *result = &list->data[i];
            pthread_mutex_unlock(&list->lock);
            return result;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void dyn_list_iterate_reverse(const dyn_list_t *list, void (*callback)(const LTEPHY_MEASUREMENT_RECORD *, void *), void *userdata) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = list->size - 1; i != 0; --i) {
        callback(&list->data[i], userdata);
    }
    pthread_mutex_unlock(&list->lock);
}

