    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdus) {
        fprintf(stderr, "Failed to allocate memory for PDUs.\n");
        return NULL;
    }

    pthread_mutex_lock(&cache_lock);

    // Populate the structures with valid data and CRC flags
    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &pdus[i];
        RX_UE_INFORMATION_TAG tag = { .id = i };
        pdu->rxUEInformationTag = tag;
        pdu->rNTI = (uint16_t)(i % MAX_RNTI);
        pdu->cRCIndicationREL8_tag.cRCFlag = calculate_crcflag(pdu);
    }

    pthread_mutex_unlock(&cache_lock);

    // Batch write to the external data source
    size_t written = 0;
    while (written < n) {
        size_t batch_size = n - written > max_cache_size ? max_cache_size : n - written;
        write_to_db(pdus + written, batch_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        written += batch_size;
    }

    // Cache the PDUs for faster retrieval
    for (size_t i = 0; i < n; ++i) {
        put_into_cache(&pdus[i]);
    }

    return pdus;
}

