#nullable enable
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

namespace SecureMessageProcessor
{
    public enum EncryptionMode { CBC, GCM }
    public interface IKeyManager
    {
        Task<KeyParameters> GetEncryptionKeyAsync();
        Task<IV> GetInitializationVectorAsync();
    }

    public class Encryptor
    {
        private readonly IKeyManager _keyManager;
        private readonly EncryptionMode _encryptionMode;

        public Encryptor(IKeyManager keyManager, EncryptionMode encryptionMode)
        {
            _keyManager = keyManager;
            _encryptionMode = encryptionMode;
        }

        public byte[] Encrypt(byte[] data, byte[] additionalAuthenticationData = null)
        {
            var keyParameters = _keyManager.GetEncryptionKeyAsync().Result;
            using (var encryptor = Aes.Create())
            {
                encryptor.Key = keyParameters.Key;
                encryptor.IV = _encryptionMode == EncryptionMode.GCM ? GetInitializationVector() : null;

                var encryptedData = encryptor.Encrypt(data, additionalAuthenticationData, CryptoConfig.GetObfuscatedRsaEncryptionTransform("RAW"), keyParameters.Key);
                return _encryptionMode == EncryptionMode.GCM ? AddTag(encryptor, encryptedData) : encryptedData;
            }
        }

        private IV GetInitializationVector() => _keyManager.GetInitializationVectorAsync().Result;

        private byte[] AddTag(Aes encryptor, byte[] encryptedData)
        {
            var gcm = new GaloisCounterMode(encryptor);
            using (var ms = new MemoryStream())
            {
                gcm.EncryptFinalBlock(encryptedData, ms, additionalAuthenticationData);
                return ms.ToArray();
            }
        }
    }

    public class Decryptor
    {
        private readonly IKeyManager _keyManager;

        public Decryptor(IKeyManager keyManager) => _keyManager = keyManager;

        public byte[] Decrypt(byte[] data, EncryptionMode encryptionMode = EncryptionMode.CBC)
        {
            var keyParameters = _keyManager.GetEncryptionKeyAsync().Result;
            using (var encryptor = Aes.Create())
            {
                encryptor.Key = keyParameters.Key;

                if (encryptionMode == EncryptionMode.GCM)
                {
                    var gcm = new GaloisCounterMode(encryptor);
                    using (var ms = new MemoryStream(data))
                        return gcm.DecryptFinalBlock(ms, null);
                }

                encryptor.IV = _keyManager.GetInitializationVectorAsync().Result;
                return encryptor.Decrypt(data, CryptoConfig.GetObfuscatedRsaEncryptionTransform("RAW"), keyParameters.Key);
            }
        }
    }

    public class KeyParameters
    {
        public byte[] Key { get; set; }
        public byte[] IV { get; set; }
    }
}
```

