from functools import wraps
from concurrent.futures import ThreadPoolExecutor, as_completed

import logging
import yaml
import mock

class ProcessDynamicDataset:
    def __init__(self, data_source, processing_config, output_format, parallelism_level, error_handling_policy, timeout_settings, retry_attempts, dependency_map):
        self.data_source = data_source
        self.processing_config = processing_config
        self.output_format = output_format
        self.parallelism_level = parallelism_level
        self.error_handling_policy = error_handling_policy
        self.timeout_settings = timeout_settings
        self.retry_attempts = retry_attempts
        self.dependency_map = dependency_map
        self.mock = mock.MockLibrary()
        self.tracer = TracingTool()
        self.log = logging.getLogger(__name__)

    async def retrieve_data(self, url):
        if url in self.cache:
            return self.cache[url]

        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(url, timeout=self.timeout_settings) as response:
                    data = await response.json()
                    self.cache[url] = data
                    return data
        except Exception as e:
            if not self.error_handling_policy.should_retry_on_error(e):
                raise e
            self.log.warning(f'Data retrieval failed for URL {url}. Retrying...')
            return await self.retrieve_data(url)

    def schedule_task(self, task):
        priority, criticality = task['priority'], task['criticality']
        tasks_queue = getattr(self, f'tasks_queue_{priority}_{criticality}') or []
        tasks_queue.append(task)
        sort_tasks(tasks_queue)

    def sort_tasks(self, tasks):
        tasks.sort(key=lambda x: x['duration'] if 'duration' in x else float('inf'), reverse=True)

    @wraps(process_fn)
    async def process_task(self, task):
        try:
            start_time = time.monotonic()
            self.log.info(f'Processing task {task["id"]}')
            self.tracer.start_task(task['id'])

            if 'dependencies' in task and task['dependencies']:
                dependencies = [self.retrieve_data(dep) for dep in task['dependencies']]
                await asyncio.gather(*dependencies)

            processed_data = await task['process_fn']()
            end_time = time.monotonic()
            duration = end_time - start_time

            self.log.info(f'Task {task["id"]} completed in {duration:.2f} seconds')
            self.tracer.end_task(task['id'])
            update_metrics(duration, processed_data)
        except Exception as e:
            self.log.error(f'Error processing task {task["id"]}: {e}')
            handle_error(e, task)

    def handle_error(self, error, task):
        if not self.error_handling_policy.should_retry_on_error(error):
            raise error
        self.log.warning(f'Retrying task {task["id"]} due to error: {error}')
        if task['retry_attempts'] < self.retry_attempts:
            schedule_task({ ...task, 'retry_attempts': task['retry_attempts'] + 1 })
        else:
            self.log.warning(f'Failed to process task {task["id"]} after {self.retry_attempts} attempts')
