const logger = log4js.getLogger();
logger.level = logLevel;

// Define the base CMS API endpoint
const cmsApiEndpoint = '/api/scripts';

// Define options for command line arguments
const args = require('minimist')(process.argv.slice(2));
const defaultOptions = {
  apiKey: process.env.CMS_API_KEY,
  fetchThreshold: 10000, // Threshold in bytes for lazy loading scripts
  maxRetries: 3, // Number of retries in case of network failures
  logLevel: logLevel, // Logging level (debug or info)
};
const options = { ...defaultOptions, ...args };

// Create Strategy instance to handle different script types
class ScriptStrategy extends Strategy {}

// Implement the fetchScript function, which retrieves a script object from the CMS API
async function fetchScript(url) {
  let response;
  for (let i = 0; i < options.maxRetries; ++i) {
    try {
      response = await axios.get(url);
      break;
    } catch (error) {
      logger.warn(`Failed to fetch script from ${url} (${error}). Retrying...`);
    }
  }

  if (!response || !response.data) {
    throw new Error(`Could not fetch script data from ${url}`);
  }

  // Parse the JSON response and validate the required fields
  const script = JSON.parse(response.data);
  if (!script || !script.key || typeof script.innerHTML !== 'string') {
    throw new Error(`Invalid script object: ${JSON.stringify(script)}`);
  }

  return script;
}

// Implement the executeScript function, which adds a validated script to the DOM safely
async function executeScript(script) {
  // Add the script element to the head of the document
  const scriptEl = document.createElement('script');
  scriptEl.innerHTML = script.innerHTML;
  document.head.appendChild(scriptEl);

  // Clean up resources when the script is removed from the dataset
  scriptEl.onremove = () => {
    logger.debug(`Script ${script.key} removed from DOM`);
    scriptEl.parentNode.removeChild(scriptEl);
  };
}

// Implement the lazyLoad function, which checks if a script exceeds the defined threshold before fetching and executing it
function lazyLoad(url) {
  const size = parseInt(fs.statSync(path.resolve(url)).size, 10);
  return size > options.fetchThreshold;
}

// Define the dynamic_script_loader function, which accepts an array of script URLs and loads them asynchronously
async function dynamicScriptLoader(scripts) {
  // Implement caching, parallel processing, and other optimizations here...

  const loadedScripts = [];

  for (const url of scripts) {
    if (!lazyLoad(url)) {
      try {
        const script = await fetchScript(url);
        await executeScript(script);
        loadedScripts.push(script);
      } catch (error) {
        logger.warn(`Error while loading ${url}: ${error}`);
      }
    }
  }

  return loadedScripts;
}

// Load the list of scripts from the CMS API using a caching mechanism
(async function main() {
  try {
    const scriptUrls = await axios.get(`${cmsApiEndpoint}`);
    const loadedScripts = await dynamicScriptLoader(scriptUrls.data);

    // Log script loading events and performance metrics here...

  } catch (error) {
    logger.error(`Error while fetching scripts from CMS API: ${error}`);
  }
})();
```

