```javascript
require('dotenv').config(); // Load environment variables
const express = require('express');
const mongoose = require('mongoose');
const axios = require('axios');
const redis = require('redis');
const { promisify } = require('util');

// Define employee schema and model
const EmployeeSchema = new mongoose.Schema({ ... });
const EmployeeModel = mongoose.model('Employee', EmployeeSchema);

// Initialize Redis client
const redisClient = redis.createClient({ ... });
const getRedisAsync = promisify(redisClient.get).bind(redisClient);
const setRedisAsync = promisify(redisClient.set).bind(redisClient);

// Initialize Express app
const app = express();
app.use(express.json());

// Database connection pooling and error handling
mongoose.connect(process.env.MONGODB_URI, {
  useNewUrlParser: true,
  useUnifiedTopology: true,
  poolSize: parseInt(process.env.DB_POOL_SIZE),
}).then(() => console.log('Connected to MongoDB'))
  .catch((err) => console.error(`MongoDB connection error: ${err}`));

// API call for geolocation data
const getGeolocationData = async (supervisorId) => {
  try {
    const response = await axios.get(`${process.env.GEOLOCATION_API_URL}/${supervisorId}`);
    return response.data;
  } catch (error) {
    console.error(`Error getting geolocation data: ${error}`);
    throw error;
  }
};

// Function to fetch employee data
const getEmployeeData = async (supervisorId, cache) => {
  // Check Redis for cached data
  const cachedData = await getRedisAsync(`employee_data:${supervisorId}`);
  if (cachedData) return JSON.parse(cachedData);

  try {
    const employeeData = await EmployeeModel.findOne({ supervisorId });
    // Cache the data in Redis for a specified time (TTL)
    setRedisAsync(`employee_data:${supervisorId}`, JSON.stringify(employeeData), 'EX', parseInt(process.env.REDIS_TTL));
    return employeeData;
  } catch (error) {
    console.error(`Error fetching employee data: ${error}`);
    throw error;
  }
};

// API endpoint for retrieving employee information based on supervisor ID
app.get('/employee/:supervisorId', async (req, res) => {
  try {
    const supervisorId = req.params.supervisorId;
    const employeeData = await getEmployeeData(supervisorId);

    if (!employeeData) throw new Error('Employee not found');

    // Fetch geolocation data and merge with the employee data
    const geolocationData = await getGeolocationData(supervisorId);
    const result = { ...employeeData.toJSON(), ...geolocationData };

    res.json(result);
  } catch (error) {
    console.error(`Error in employee data retrieval: ${error}`);
    res.status(500).send('Internal Server Error');
  }
});

// Start the service
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`EmployeeDirectoryService listening on port ${PORT}`));
```

