void list_iterate_reverse(struct list* list, void (*func)(measurement_record)) {
    pthread_mutex_lock(&head_semaphore);
    list_node *current = list->head;
    list->head = current->next;
    pthread_mutex_unlock(&head_semaphore);

    while (current != NULL) {
        list_node *next = current->next;
        (*func)(current->data);
        // Store position and unlock to allow other operations, then lock again before updating current
        pthread_mutex_lock(&head_semaphore);
        current = next;
        pthread_mutex_unlock(&head_semaphore);
