class DataStore {
private:
    std::map<int, int> data;
    mutex mtx;
public:
    void addData(int key) {
        std::unique_lock<mutex> lock(mtx);
        if (key < -1000 || key > 1000) return;
        data[key]++;
        lock.unlock();
        notifyMaxChanged();
    }
    int getMax() const {
        std::unique_lock<mutex> lock(mtx);
        // Return the maximum value stored in the data structure
        auto it = std::rbegin(data)->first;
        return it;
    }
private:
    condition_variable cv;
    int maxValue = INT32_MIN;
    void notifyMaxChanged() {
        std::unique_lock<mutex> lock(mtx);
        if (maxValue < getMax()) {
            maxValue = getMax();
            cv.notify_one();
        }
        lock.unlock();
    }
public:
    void waitForMaxUpdate() {
        std::unique_lock<mutex> lock(mtx);
        cv.wait(lock, [this]{return maxValue != INT32_MIN; });
    }
};

