```java
public class StringUtils {
    public static char[] appendSuffix(char[] input, int sizeLimit, boolean isSecure) {
        if (input.length <= sizeLimit && isSecure) {
            char[] suffix = "Secure".toCharArray();
            char[] result = new char[input.length + suffix.length];
            System.arraycopy(input, 0, result, 0, input.length);
            System.arraycopy(suffix, 0, result, input.length, suffix.length);
            return result;
        } else {
            return input;
        }
    }
}
```']

