package com.globalBank.transaction.service;

import com.globalBank.transaction.api.TransactionApi;
import com.globalBank.transaction.model.TransactionRequest;
import com.globalBank.transaction.model.TransactionResponse;
import com.google.protobuf.InvalidProtocolBufferException;
import io.grpc.StatusRuntimeException;

public class TransactionServiceImpl implements TransactionApi {
    private final TransactionValidator transactionValidator;
    private final InMemoryCacheManager cacheManager;
    private final PersistentStorageAdapter storageAdapter;

    public TransactionServiceImpl(TransactionValidator transactionValidator, InMemoryCacheManager cacheManager, PersistentStorageAdapter storageAdapter) {
        this.transactionValidator = transactionValidator;
        this.cacheManager = cacheManager;
        this.storageAdapter = storageAdapter;
    }

    @Override
    public TransactionResponse processTransaction(TransactionRequest request) {
        try {
            transactionValidator.validate(request);
            Object cachedResult = cacheManager.get(request.getId());
            if (cachedResult != null) {
                return (TransactionResponse) cachedResult;
            }
            // Process and store the transaction, then retrieve it from cache for future requests
        } catch (InvalidProtocolBufferException | StatusRuntimeException e) {
            throw new RuntimeException("Invalid transaction request", e);
        }
    }
}
```

