['```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using System.Web;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Caching.Distributed;
using Microsoft.Extensions.Logging;
using StackExchange.Redis;

namespace GlobalCMS.API
{
    public class ContentService : ControllerBase
    {
        private readonly ILogger<ContentService> _logger;
        private readonly IDistributedCache _cache;
        private readonly ConnectionMultiplexer _redis;

        public ContentService(ILogger<ContentService> logger, IDistributedCache cache, ConnectionMultiplexer redis)
        {
            _logger = logger;
            _cache = cache;
            _redis = redis;
        }

        [HttpPut]
        public async Task<IActionResult> UpdateContent([FromBody] UpdateRequest request)
        {
            if (!ModelState.IsValid)
                return BadRequest(ModelState);

            var authenticationProvider = new AuthenticationService(_logger, _redis);
            if (!await authenticationProvider.Validate(request.ApiKey))
                return Unauthorized();

            var contentRepository = new ContentRepository(_cache);

            try
            {
                await contentRepository.Update(request.PageId, request.SectionId, request.ElementId, request.Metadata, request.Content);
                return Ok();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to update content");
                return StatusCode(500, "An error occurred while updating content.");
            }
        }
    }

