[' ```cpp
   #include <iostream>
   #include <chrono>
   #include <thread>
   #include <random>
   #include <unistd.h>

   // Namespace for the DynamicCombatHub service
   namespace DynamicCombatHub {

       // Forward declaration of the RandomAttackSelector function
       void RandomAttackSelector();

       // Global random number generator to ensure thread safety
       std::mt19937 rng;

       // Initialize the global random number generator
       inline void init_rng() {
           unsigned seed = std::chrono::high_resolution_clock::now().time_since_epoch().count();
           rng.seed(seed);
       }

       // Function to select a random attack with cooldown period
       void RandomAttackSelector() {
           static bool onCooldown = true;
           static std::uniform_int_distribution<int> dist(0, 1);

           if (onCooldown) {
               init_rng();
               auto start_time = std::chrono::high_resolution_clock::now();

               // Wait for the cooldown period of 9 seconds
               constexpr int cooldown_ms = 9 * 1000;
               while (std::chrono::duration_cast<std::chrono::milliseconds>(
                           std::chrono::high_resolution_clock::now() - start_time).count() < cooldown_ms) {}

               onCooldown = false;
           }

           if (!onCooldown) {
               int attackNum = dist(rng);
               std::cout << "Selected attack: " << attackNum << std::endl;
               onCooldown = true;
           }
       }
   } // namespace DynamicCombatHub

   // Main function to start the RandomAttackSelector function in an infinite loop
   int main() {
       while (true) {
           DynamicCombatHub::RandomAttackSelector();
           usleep(1000); // Sleep for a very short time before restarting
       }
       return 0;
   }
```

