        let rss_before = unsafe { libc::getrusage().ru_maxrss };
        let result = self.rustc_driver.call(vec![String::from("-C"), crate_name]).await;
        let rss_after = unsafe { libc::getrusage().ru_maxrss };
        let elapsed = start.elapsed().as_millis();

