2. C Function (process_data.c)

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    size_t line_length;
    char* line;
} LineData;

void read_file(const char *filename, LineData **lines) {
    FILE *file = fopen(filename, "r");
    if (!file) return;

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    rewind(file);

    *lines = malloc(sizeof(LineData) * file_size);

    LineData *current = *lines;
    for (size_t i = 0; i < file_size; ++i) {
        current->line_length = getline(&(current->line), &current->line_length, file);
        if (current->line_length <= 0) break;
        current++;
    }
}

void process_data(LineData lines[], size_t num_lines) {
    for (size_t i = 0; i < num_lines; ++i) {
        char *token = strtok(lines[i].line, " ");
        if (!token) continue;

        double value1 = atof(token);
        token = strtok(NULL, " ");
        double value2 = (token ? atof(token) : 0.0);

        printf("%f\n", (value1 + value2) / 2.0);
    }
}

void free_line_data(LineData lines[], size_t num_lines) {
    for (size_t i = 0; i < num_lines; ++i) {
        free(lines[i].line);
    }
    free(lines);
}

int main(int argc, char* argv[]) {
    const char *filename = (argc > 1) ? argv[1] : "data.bin";
    LineData *lines;
    read_file(filename, &lines);

    process_data(lines, strlen(filename) / sizeof(LineData));
    free_line_data(lines, strlen(filename) / sizeof(LineData));

    return 0;
}
```']

