4. Dynamic Linked List Function (C):

```c
#include <stdlib.h>
#include <stdio.h>

typedef struct {
    void *data;
    NFAPI_CRC_INDICATION_PDU_T* pdu;
    struct Node* next;
} Node;

Node* create_node(void* data, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->data = data;
    node->pdu = pdu;
    node->next = NULL;
    return node;
}

void free_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp->data);
        free(temp);
    }
}
```"]

