const express = require('express');
const { validateMediaPayload } = require('./middleware/Validator');
const MediaService = require('./services/MediaService');
const RetryStrategy = require('./utils/RetryStrategy');

const mediaRouter = express.Router();

mediaRouter.post('/upload', validateMediaPayload, async (req, res) => {
  try {
    const media = await MediaService.processMedia(req.body);
    res.json({ status: 'success', data: media });
  } catch (error) {
    // Log the error and implement retry strategy for transient errors
    if (RetryStrategy.shouldRetry(error)) {
      // Retry the request after a defined delay
      setTimeout(() => {
        res.status(503).json({ status: 'retry', error: error.message });
      }, RetryStrategy.getDelay(error));
    } else {
