NFAPI_CRC_INDICATION_PDU_T* populateNfarxIndications(size_t N) {
    if (N <= 0) {
        fprintf(stderr, "Invalid input: N should be greater than zero.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        perror("Memory allocation failed.\n");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    #pragma GCC ivdep
    for (size_t i = 0; i < N; ++i) {
        indications[i].RX_UE_INFORMATION_TAG = i + 1;
        indications[i].RNTI = rand() % MAX_RNTI;
        indications[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        indications[i].CRCFLAG = rand() % 2;
    }

    free(mutex); // Mutex is no longer needed, so we can free it here.
    return indications;
}
