2. JavaScript function to extract book names from Bible's Old Testament:

```javascript
const regex = /(\b[A-Z]{3,}\b|\b[A-Z] [A-Z]{2,}\b)(?: [A-Z][a-z]*|(?: \d+:\d+,\s*)+)?/g;

function extractBookNames(text) {
    const matches = [];
    let match;
    while (match = regex.exec(text)) {
        matches.push(match[1]);
    }

    const bookCounts = {};
    for (const book of matches) {
        if (!bookCounts.hasOwnProperty(book)) {
            bookCounts[book] = 0;
        }
        bookCounts[book]++;
    }
    return bookCounts;
}
```']

