    env::var("CRC_DIR").ok().map(|v| PathBuf::from(v))
}

fn get_or_create_crc_dir() -> Result<PathBuf, Box<dyn std::error::Error>> {
    let mut dir = match get_crc_dir() {
        Some(d) => d,
        None => {
            let timestamp = chrono::Utc::now().format("%Y%m%d-%H%M%S").to_string();
            let tempfile = NamedTempFile::new_in("./temp")?;
            PathBuf::from(tempfile.path().join(&format!("NFAPI_CRC_INDICATION_{}", timestamp)))
        }
    };

    fs::create_dir_all(&dir)?;
    Ok(dir)
}

// System Integration
async fn fetch_and_store_pdus(dir: PathBuf) -> Result<(), Box<dyn std::error::Error> {
    let client = Client::new();
    const MAX_RETRIES: u32 = 5;
    let mut retries = 0;

    loop {
        match client.get(EXTERNAL_API_URL).send().await? {
            Response { status, text } => match (status.as_u16(), text) {
                (200, Ok(_)) => {
                    let pdus: Vec<NFAPI_CRC_INDICATION_PDU_T> = serde_json::from_str(&text)?;
                    store_pdus(dir.clone(), &pdus)?;
                    break;
                }
                (_, error) => {
                    if retries < MAX_RETRIES {
                        info!("External API request failed, retrying: {}", error);
                        retries += 1;
                        continue;
                    } else {
                        return Err(Box::new(error));
                    }
                }
            },
        }
    }
}

fn store_pdus(dir: PathBuf, pdus: &[NFAPI_CRC_INDICATION_PDU_T]) -> Result<(), Box<dyn std::error::Error>> {
    let file = File::create(dir.join("pdus.json"))?;
    let mut writer = BufWriter::new(file);
    serde_json::to_writer(&mut writer, pdus)?;
    Ok(())
}
