fn initialize_crc_directory(config: Config) {
    let dir_path = match env::var("CRC_DIR") {
        Ok(val) => PathBuf::from(val),
        Err(_) => {
            let timestamp = chrono::Utc::now().timestamp();
            let random_id = Uuid::new_v4().to_string();
            let parent_dir = &config.parent_dir;
            parent_dir.join(format!("NFAPI_CRC_{}_{}", timestamp, random_id))
        }
    };

    if !fs::create_dir_all(&dir_path).is_ok() {
        eprintln!("Failed to create directory: {}", dir_path.display());
        return;
    }

    let mut file_map = HashMap::new();

    let client = Client::new();

    loop {
        match spawn_blocking(move || fetch_pdus(&config, &client))
            .await
            .unwrap()
        {
            pdus @ ..= config.batch_size => {
                for pdu in pdus {
                    let file = dir_path.join(format!("{}.txt", pdu.RNTI));

                    if !file_map.contains_key(&pdu.RNTI) {
                        let file = File::create(&file).unwrap();
                        let writer = BufWriter::new(file);
                        writeln!(writer, "{}", pdu).unwrap();
                        file_map.insert(pdu.RNTI, file);
                    }
                }
            }
            _ => {
                // Handle the batch processing with backpressure and rate limiting here.
            }
        }

        break;
    }

    let files = take(file_map.drain());

    for (k, v) in files {
        if !v.flush().is_err() && v.sync_all().is_ok() {
            // Log successful write here
        } else {
            eprintln!("Failed to write file {}: {}", k, v.display());
        }
    }
}
