[' Due to the complexity of your request, I will provide a high-level design for your distributed semaphore system in C, using Pthreads for threading and Redis as an external configuration management system. Note that implementing this solution would require integrating it with your specific application architecture, monitoring system, and security measures.

1. Semaphore struct definition:

```c
#include <pthread.h>
#include <stdbool.h>
#include <Redis.h>

struct semaphore {
    RedisContext *redis;
    pthread_mutex_t lock;
    int current, max;
    char* key;
};
```

2. Semaphore creation function:

```c
void create_semaphore(struct semaphore** sem, const char* key, int initial_value, int max_count) {
    *sem = malloc(sizeof(struct semaphore));
    (*sem)->redis = redisConnect("localhost", 6379); // Replace with your Redis server details
    (*sem)->lock = PTHREAD_MUTEX_INITIALIZER;
    (*sem)->current = initial_value;
    (*sem)->max = max_count;
    (*sem)->key = strdup(key);
}
```

3. Semaphore destruction function:

```c
void delete_semaphore(struct semaphore** sem) {
    free((*sem)->key);
    free(*sem);
}
```

4. Acquire the semaphore function:

```c
int acquire_semaphore(struct semaphore *sem, int timeout_ms) {
    pthread_mutex_lock(&sem->lock);
    while ((*sem)->current >= (*sem)->max && pthread_mutex_trylock(sem->redis->mutex)) {
        redisSyncWithMaster(sem->redis);
        if (pthread_mutex_unlock(&sem->lock)) {
            // Handle error and unlock mutex before returning
            return -1;
        }
        usleep(timeout_ms < 0 ? 500 : timeout_ms);
    }
    if ((*sem)->current < (*sem)->max) {
        ++(*sem)->current;
    } else {
        // Handle error and unlock mutex before returning
        return -1;
    }
    pthread_mutex_unlock(&sem->lock);

    // Perform atomic update to Redis
    redisCommand(sem->redis, "SET %s %d", sem->key, (*sem)->current);
    return 0;
}
```

5. Release the semaphore function:

```c
void release_semaphore(struct semaphore *sem) {
    pthread_mutex_lock(&sem->lock);
    if ((*sem)->current > 0) {
        --(*sem)->current;
    } else {
        // Handle error and unlock mutex before returning
        return;
    }
    pthread_mutex_unlock(&sem->lock);

    // Perform atomic update to Redis
    redisCommand(sem->redis, "SET %s %d", sem->key, (*sem)->current);
}
```

6. Implement resource leasing and throttling mechanism:

- Maintain a list of active acquisitions for each semaphore.
- Lease the semaphore by adding an acquisition to the active list and removing it when released.
- Implement a configurable throttle limit using Redis to store the number of active acquisitions per semaphore, with backoff strategy based on the severity of overload.']

