public class FetchAndProcessUserActivityLogsAsync
{
    private readonly IConfiguration _configuration;
    private readonly ILogger _logger;
    private readonly IConnectionMultiplexer _redis;
    private readonly HttpClient _httpClient;
    private readonly AsyncStreamingCall<LogEntry> _call;

    public FetchAndProcessUserActivityLogsAsync(IConfiguration configuration, ILogger<FetchAndProcessUserActivityLogsAsync> logger, IConnectionMultiplexer redis, HttpClient httpClient)
