    public async Task FetchAndProcessUserActivityLogsAsync(CancellationToken cancellationToken)
    {
        var apiKey = _configuration["ApiKeys:LoggingService"];
        var logLevel = _configuration["LogLevels:Minimum"];
        var timeWindow = TimeSpan.Parse(_configuration["TimeWindows:Duration"]);

        var cacheKey = "user_activity_logs:" + logLevel;

        var redisCache = _redis.GetDatabase();

        // Check if data is already in cache, use it if available (< timeWindow).
        if (redisCache.KeyExists(cacheKey))
        {
            var jsonLogs = redisCache.StringGet(cacheKey);
            var logs = JsonSerializer.Deserialize<List<LogEntry>>(jsonLogs);
            ProcessUserActivityLogs(logs, cancellationToken);
            return;
        }

        var policy = Policy
            .Handle<Exception>()
            .OrResult<HttpResponseMessage>(r => r.IsSendError())
            .WaitAndRetryAsync(
                retryCount: 10,
                sleepDurationProvider: (retryAttempt) => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)),
                OnTransientExecutionFailure = (exception, retryCount, context) =>
                {
                    _logger.LogError(exception, "Failed to fetch logs; retrying in {retryWait} seconds.", retryWait: retryCount);
                }
            );

        var response = await policy.ExecuteAsync(() => FetchLogsAsync(_httpClient, apiKey, cancellationToken), cancellationToken);

        if (!response.IsSuccessStatusCode)
        {
            _logger.LogError("Failed to fetch logs; status code: {statusCode}", response.StatusCode);
            return;
        }

        var logs = JsonSerializer.Deserialize<List<LogEntry>>(await response.Content.ReadAsStringAsync());
        ProcessUserActivityLogs(logs, cancellationToken);

        // Cache the fetched logs for future use (if they haven't aged out).
        if (DateTime.UtcNow - logs.First().Timestamp < timeWindow)
        {
            redisCache.StringSet(cacheKey, JsonSerializer.Serialize(logs), expires: TimeSpan.FromHours(1));
        }
    }

