void generateCrcIndications(int N, NFAPI_CRC_INDICATION_PDU_T* list) {
  if (N <= 0) {
    printf("Error: Invalid input size\n");
    return;
  }

  unsigned long rntis[N]; // Store unique RNTI values here
  int used = 0;
  NFAPI_CRC_INDICATION_PDU_T* pool = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

  if (!pool) {
    printf("Error: Insufficient memory to create list\n");
    free(rntis); // Free any allocated resources upon encountering an error
    return;
  }

  // Use a read-write lock here to optimize read-heavy operations while maintaining thread safety

  for (int i = 0; i < N; ++i) {
    int j;
    for (j = 0; j < used && rntis[j] != 0; ++j); // Find an unused RNTI value

    if (j == used) {
      printf("Error: Out of unique RNTI values\n");
      free(rntis); // Free any allocated resources upon encountering an error
      free(pool);
      return;
