    rntis[j] = i + 1; // Mark the current RNTI as used
    pool[i].RX_UE_INFORMATION_TAG = rand(); // Set other fields here with appropriate values
    pool[i].RNTI = rntis[j];
    pool[i].CRC_INDICATION_REL8_TAG = rand() % 2;
