FSA* create_state_list(int *states, int num_states, FSA *fsa, int last_state) {
    FSA *new_fsa = malloc(sizeof(FSA));
    if (!new_fsa) return NULL;

    new_fsa->num_states = num_states;
    new_fsa->states = malloc(num_states * sizeof(int));
    if (!new_fsa->states) {
        free(new_fsa);
        return NULL;
    }
    memcpy(new_fsa->states, states, num_states * sizeof(int));

    for (int i = 0; i < num_states; ++i)
        next(new_fsa->states[i]);

    new_fsa->next = fsa->next;
    new_fsa->states[last_state] = -1; // Mark the last state as the new start state

    return new_fsa;
}
