void add_state_to_fsa(FSAState **fsa, int state_id) {
    FSAState *new_state = malloc(sizeof(FSAState));
    new_state->id = state_id;
    new_state->next = NULL;

    if (!*fsa) {  // FSA is empty
        *fsa = new_state;
    } else {
        FSAState *current = *fsa;
        while (current->next) {
            current = current->next;
        }
        current->next = new_state;
    }
}
```

