['```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <pthread.h>
#include <err.h>
#include <time.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <signal.h>
#include <stdbool.h>
#include <sys/mman.h>
#include <sqlite3.h>
#include <librabbitmq/rabbit_c.h>

typedef struct {
    int id;
    int value;
} record;

struct config {
    size_t num_records;
    int min, max;
};

int read_config(const char *file, struct config *cfg) {
    FILE *fp = fopen(file, "r");
    if (!fp) return -1;

    if (fscanf(fp, "%ld\n%d %d", &cfg->num_records, &cfg->min, &cfg->max) != 3) {
        err(1, "%s: invalid configuration format", file);
    }

    fclose(fp);
    return 0;
}

void *generate_random_value(void *arg) {
    struct config *cfg = arg;
    while (true) {
        int rand_val = (rand() % (cfg->max - cfg->min + 1)) + cfg->min;
        if ((long long)rand_val <= LLONG_MAX - cfg->value) {
            break;
        }
    }
    return (void *)rand_val;
}

int main() {
    struct config cfg;
    if (read_config("config.txt", &cfg) == -1) {
        err(1, "Failed to read configuration file");
    }

    pthread_t threads[cfg.num_records];
    record *records = mmap(NULL, sizeof(record) * cfg.num_records, PROT_READ | PROT_WRITE, MAP_ANON | MAP_SHARED, -1, 0);
    if (records == MAP_FAILED) {
        err(1, "Failed to allocate memory");
    }

    for (size_t i = 0; i < cfg.num_records; ++i) {
        pthread_create(&threads[i], NULL, generate_random_value, &cfg);
    }

    for (size_t i = 0; i < cfg.num_records; ++i) {
        void *val;
        pthread_join(threads[i], &val);
        records[i].value = *(int *)val;
    }

    // Database and message queue integration, health-checking, scaling, etc.

    munmap(records, sizeof(record) * cfg.num_records);
    return 0;
