    private IDatabase Database;
    private string ConnectionString;

    public void Initialize(string redisConnection, string dbConnection)
    {
        _redis = ConnectionMultiplexer.Connect(redisConnection);
        Database = _redis.GetDatabase();
        ConnectionString = dbConnection;
    }

    public DataTableReader SendDataAndGetResultSet(object data)
    {
        var serializer = new BinaryFormatter();
        using (var connection = new SqlConnection(ConnectionString))
        {
            connection.Open();
            using (var command = new SqlCommand("StoredProcedure", connection))
            {
                command.CommandType = CommandType.StoredProcedure;
                using (var binaryStream = new MemoryStream())
                {
                    serializer.Serialize(binaryStream, data);
                    command.Parameters.Add("@serializedData", SqlDbType.Binary).Value = binaryStream.ToArray();
                }
                using (var reader = command.ExecuteReader())
                {
                    return new DataTableReader(reader);
                }
            }
        }
    }

    public void SaveToRedis(string key, object value)
    {
        Database.StringSet(key, JsonConvert.SerializeObject(value));
    }
}
