    {
        // Implement validation logic here, handle schema violations gracefully
        // Perform partial updates based on validation results if necessary
    }

    private async Task SaveToDatabaseAsync(ActivityLog activityLog)
    {
        try
        {
            await _databaseContext.SaveChangesAsync();
        }
        catch (DbUpdateException ex) when (ex.InnerException is DbEntityValidationException dbEx && dbEx.Entry.State == EntityState.Unchanged)
        {
            // Handle the case where an entity doesn't meet validation rules, but no other changes were made to the context.
            await UpdateAndSaveAsync(activityLog);
        }
    }

    private async Task UpdateAndSaveAsync(ActivityLog activityLog)
    {
        foreach (var entry in _databaseContext.ChangeTracker.Entries<ActivityLog>())
        {
            if (entry.State == EntityState.Modified)
