        pthread_mutex_lock(&array_mutex);
        array[num_structures].tag = generate_random_tag();
        array[num_structures].rnti = rnti;
        array[num_structures].crc_indication = generate_random_crc_indication();
        array[num_structures].crcflag = rand() % 2 == 0;
        num_structures++;
        pthread_mutex_unlock(&array_mutex);
    }

    gettimeofday(&end, NULL);
    log(LOG_LEVEL_INFO, "Populated array with %zu structures in %ld seconds.", num_structures, (end.tv_sec - start.tv_sec));

    cleanup_db(params);

    return NULL;
}

int main() {
