    pthread_t workers[NUM_WORKERS];
    int i;

    init_db(&params, "path/to/database.db");

    for (i = 0; i < NUM_WORKERS; ++i) {
        if (pthread_create(&workers[i], NULL, &worker, &params)) {
            log(LOG_LEVEL_ERROR, "Failed to create worker thread.");
            return -1;
        }
    }

    for (i = 0; i < NUM_WORKERS; ++i) {
        pthread_join(workers[i], NULL);
    }

    cleanup_db(&params);

    populate_array(array, MAX_STRUCTURES);

    return 0;
}
